CREATE DATABASE IF NOT EXISTS vibechecks CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE vibechecks;
CREATE TABLE bank_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nickname VARCHAR(100) NOT NULL,account_holder VARCHAR(180) NOT NULL,address1 VARCHAR(180),address2 VARCHAR(180),city VARCHAR(100),state VARCHAR(50),postal_code VARCHAR(20),phone VARCHAR(40),email VARCHAR(180),date_format VARCHAR(20) NOT NULL DEFAULT 'MM/DD/YYYY',bank_name VARCHAR(180) NOT NULL,routing_number VARCHAR(20) NOT NULL,account_number VARCHAR(34) NOT NULL,next_check_number INT UNSIGNED NOT NULL DEFAULT 1001,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE payees (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,address1 VARCHAR(180),address2 VARCHAR(180),city VARCHAR(100),state VARCHAR(50),postal_code VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_payee_name(name));
CREATE TABLE checks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,bank_account_id BIGINT UNSIGNED NOT NULL,payee_id BIGINT UNSIGNED NULL,check_number INT UNSIGNED NOT NULL,check_date DATE NOT NULL,payee_name VARCHAR(180) NOT NULL,amount DECIMAL(12,2) NOT NULL,amount_words VARCHAR(500) NOT NULL,memo VARCHAR(255),status ENUM('draft','printed','void','cleared') NOT NULL DEFAULT 'draft',printed_at DATETIME,cleared_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_account_check(bank_account_id,check_number),FOREIGN KEY(bank_account_id) REFERENCES bank_accounts(id),FOREIGN KEY(payee_id) REFERENCES payees(id) ON DELETE SET NULL);